  "qa": [
    {
      "question": "会议中提到的主持人选拔方案是什么？",
      "answer": "会议决定由空乘系和播音专业两个系别分别竞选主持人，最终选出4名合格主持人并配备至少2名备用人员，需提前1-2周进行选拔考核。"
    },
    {
      "question": "节目排序和互动环节的安排原则是什么？",
      "answer": "节目需在学生报名后按类别进行有序排列，避免穿插混杂，同时可设计师生互动游戏环节，如抛绣球活动以增强现场参与感。"
    },
    {
      "question": "主持人选拔的具体实施步骤是什么？",
      "answer": "由负责人与部长联合向空乘班和播音专业班级发布通知，征集报名后进行筛选，确保选出4名主持人并预留2名替补。"
    }
  ]
}
